<?php
require_once __DIR__ . '/config/bootstrap.php';
require_once __DIR__ . '/config/auth.php';
require_staff();

if(!isset($_SESSION['user_id'])&&!isset($_SESSION['usuario_id'])){header('Location:login.php');exit;}
require_once 'config/database.php';$db=getDBConnection();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);
if(!$id){$_SESSION['error']='Consulta inválida.';header('Location:historial.php');exit;}
$q=$db->prepare("SELECT co.*,m.nombre mascota,c.nombre cliente FROM consultas co LEFT JOIN mascotas m ON m.id=co.mascota_id LEFT JOIN clientes c ON c.id=co.cliente_id WHERE co.id=?");$q->execute([$id]);$co=$q->fetch(PDO::FETCH_ASSOC);if(!$co){$_SESSION['error']='Consulta no encontrada.';header('Location:historial.php');exit;}
$vets=$db->query("SELECT id,nombre FROM usuarios WHERE rol IN ('veterinarian','admin') AND estado='active' ORDER BY nombre")->fetchAll(PDO::FETCH_ASSOC);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $fecha=trim($_POST['fecha_consulta']??'');$motivo=trim($_POST['motivo']??'');$signos=trim($_POST['signos_clinicos']??'');$diag=trim($_POST['diagnostico']??'');$proc=trim($_POST['procedimiento']??'');$trat=trim($_POST['tratamiento']??'');$pend=trim($_POST['pendientes']??'');$obs=trim($_POST['observaciones']??'');$valor=str_replace(',','.',trim($_POST['valor_total']??'0'));$vetid=filter_var($_POST['veterinario_id']??null,FILTER_VALIDATE_INT);
 if(!$fecha||!DateTime::createFromFormat('Y-m-d',$fecha))$error='Fecha inválida.';elseif($motivo==='')$error='El motivo es obligatorio.';elseif($diag==='')$error='El diagnóstico es obligatorio.';elseif(!is_numeric($valor)||$valor<0)$error='El valor total no es válido.';else{
  $vet='';if($vetid){$v=$db->prepare("SELECT nombre FROM usuarios WHERE id=? AND rol IN ('veterinarian','admin')");$v->execute([$vetid]);$vet=(string)$v->fetchColumn();if($vet==='')$vetid=null;}
  $u=$db->prepare('UPDATE consultas SET fecha_consulta=?,motivo=?,signos_clinicos=?,diagnostico=?,procedimiento=?,tratamiento=?,pendientes=?,valor_total=?,observaciones=?,veterinario=?,veterinario_id=? WHERE id=?');$u->execute([$fecha,$motivo,$signos,$diag,$proc,$trat,$pend,$valor,$obs,$vet,$vetid,$id]);$_SESSION['success']='Consulta actualizada correctamente.';header('Location:historial.php');exit;
 }
 $co=array_merge($co,['fecha_consulta'=>$fecha,'motivo'=>$motivo,'signos_clinicos'=>$signos,'diagnostico'=>$diag,'procedimiento'=>$proc,'tratamiento'=>$trat,'pendientes'=>$pend,'valor_total'=>$valor,'observaciones'=>$obs,'veterinario_id'=>$vetid]);
}
?>
<!doctype html><html lang="es"><head>
<?php if(function_exists('av_head')) av_head(); ?><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editar consulta</title><style>body{font-family:Arial;background:#f5f7f6;color:#26352d;margin:0}.w{max-width:900px;margin:30px auto;padding:16px}.c{background:white;padding:28px;border-radius:16px;box-shadow:0 8px 30px #0001}.g{display:grid;grid-template-columns:1fr 1fr;gap:14px}.f{grid-column:1/-1}label{display:block;font-weight:700;margin-bottom:5px}input,select,textarea{width:100%;box-sizing:border-box;border:1px solid #cdd8d1;border-radius:8px;padding:10px}textarea{min-height:90px}.btn{padding:11px 17px;border:0;border-radius:8px;text-decoration:none}.p{background:#0f6c33;color:#fff}.s{background:#edf1ee;color:#26352d}.a{display:flex;gap:10px;margin-top:20px}.e{background:#fff0ef;color:#9f241a;padding:10px;border-radius:8px}@media(max-width:650px){.g{grid-template-columns:1fr}.f{grid-column:1}}</style>    <link rel="stylesheet" href="css/app-optimized.css?v=20260812c">
</head><body><div class="w"><div class="c"><h1>Editar consulta #<?=$id?></h1><p><?=htmlspecialchars($co['mascota']??'')?> · <?=htmlspecialchars($co['cliente']??'')?></p><?php if($error):?><div class="e"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><?php echo av_csrf_field(); ?><input type="hidden" name="id" value="<?=$id?>"><div class="g"><div><label>Fecha</label><input type="date" name="fecha_consulta" required value="<?=htmlspecialchars($co['fecha_consulta']??'')?>"></div><div><label>Veterinario</label><select name="veterinario_id"><option value="">Sin asignar</option><?php foreach($vets as $v):?><option value="<?=$v['id']?>" <?=((int)$co['veterinario_id']===(int)$v['id'])?'selected':''?>><?=htmlspecialchars($v['nombre'])?></option><?php endforeach;?></select></div><div class="f"><label>Motivo *</label><textarea name="motivo" required><?=htmlspecialchars($co['motivo']??'')?></textarea></div><div class="f"><label>Signos clínicos</label><textarea name="signos_clinicos"><?=htmlspecialchars($co['signos_clinicos']??'')?></textarea></div><div class="f"><label>Diagnóstico *</label><textarea name="diagnostico" required><?=htmlspecialchars($co['diagnostico']??'')?></textarea></div><div><label>Procedimiento</label><textarea name="procedimiento"><?=htmlspecialchars($co['procedimiento']??'')?></textarea></div><div><label>Tratamiento</label><textarea name="tratamiento"><?=htmlspecialchars($co['tratamiento']??'')?></textarea></div><div><label>Pendientes</label><textarea name="pendientes"><?=htmlspecialchars($co['pendientes']??'')?></textarea></div><div><label>Valor total</label><input type="number" min="0" step="0.01" name="valor_total" value="<?=htmlspecialchars($co['valor_total']??'0')?>"></div><div class="f"><label>Observaciones</label><textarea name="observaciones"><?=htmlspecialchars($co['observaciones']??'')?></textarea></div></div><div class="a"><button class="btn p">Guardar cambios</button><a class="btn s" href="historial.php">Cancelar</a></div></form></div></div></body></html>
